insert into public.digirole_techniques (name,origin,grade,ds_cost,field,category,target,accuracy_formula,damage_formula,description,source_page)
select name,origin,grade,ds_cost,field,category,target,accuracy_formula,damage_formula,description,source_page
from jsonb_to_recordset($catalog$[{"name":"Wolkenapalm III","origin":"","grade":"V","ds_cost":0,"field":"DR","category":"Física","target":"1 inimigo","accuracy_formula":"DEX + Fight","damage_formula":"STR + 3","description":"Concentra chamas, pressão dracônica e Dados destrutivos em um ataque corporal reforçado contra o alvo escolhido. A manifestação se desfaz após a resolução, deixando apenas as condições e modificadores registrados no efeito.","source_page":252},{"name":"X-Aura","origin":"","grade":"VI","ds_cost":0,"field":"Neutra","category":"Suporte","target":"todos os aliados","accuracy_formula":"WIS + Weapons","damage_formula":"-","description":"Efeito: Recupera 3 HP de cada alvo. Reorganiza os Dados do alvo com Dados digitais sem afinidade de Field, restaurando sua estrutura conforme o efeito indicado. A energia percorre as áreas danificadas e recompõe gradualmente o padrão digital afetado.","source_page":252},{"name":"X-Heal","origin":"","grade":"V","ds_cost":0,"field":"Neutra","category":"Suporte","target":"1 aliado","accuracy_formula":"WIS + Weapons","damage_formula":"-","description":"Efeito: Recupera 4 HP. Reorganiza os Dados do alvo com Dados digitais sem afinidade de Field, restaurando sua estrutura conforme o efeito indicado. A energia percorre as áreas danificadas e recompõe gradualmente o padrão digital afetado.","source_page":252},{"name":"X-Revive","origin":"","grade":"VI","ds_cost":0,"field":"Neutra","category":"Suporte","target":"1 aliado","accuracy_formula":"WIS + Weapons","damage_formula":"-","description":"Efeito: Remove Nocaute e devolve o alvo com 4 HP. Reorganiza os Dados do alvo com Dados digitais sem afinidade de Field, restaurando sua estrutura conforme o efeito indicado. A energia percorre as áreas danificadas e recompõe","source_page":252}]$catalog$::jsonb) as x(name text,origin text,grade text,ds_cost integer,field text,category text,target text,accuracy_formula text,damage_formula text,description text,source_page integer)
on conflict (name,origin,grade) do update set ds_cost=excluded.ds_cost,field=excluded.field,category=excluded.category,target=excluded.target,accuracy_formula=excluded.accuracy_formula,damage_formula=excluded.damage_formula,description=excluded.description,source_page=excluded.source_page;
